/** Checks the actual shipped bytes, shared by build, pack and clean-install proofs. */
export function validateBinaries(id, addon, supervisor) {
  const p = PLATFORMS[id];
  assert(p, `unknown platform ${id}`);
  for (const file of [addon, supervisor]) assert(existsSync(file), `${file} is missing: build it first (npm/README.md)`);
  const want = { format: FORMAT[p.os], cpu: p.cpu };
  const lib = inspect(addon);
  assert.deepEqual({ format: lib.format, cpu: lib.cpu }, want, `${addon} is not a ${id} addon`);
  const sup = inspect(supervisor);
  assert.deepEqual({ format: sup.format, cpu: sup.cpu }, want, `${supervisor} is not a ${id} supervisor`);
  if (p.os === "linux") {
    assert(sup.static, `${supervisor} is dynamically linked: the Linux supervisor is the static musl build`);
    const musl = lib.needed.filter((n) => /^libc\.musl-|^ld-musl-|^libc\.so$/.test(n));
    const glibc = lib.needed.filter((n) => n === "libc.so.6");
    assert.equal(
      p.libc === "musl" ? musl.length > 0 && glibc.length === 0 : glibc.length > 0 && musl.length === 0,
      true,
      `${addon} is not a ${p.libc} addon: it needs ${JSON.stringify(lib.needed)}${p.libc === "musl" ? " (build it with RUSTFLAGS=\"-C target-feature=-crt-static\")" : ""}`,
    );
  }
  return { addon: lib, supervisor: sup };
}

export function validateRuntimeIdentity(identity, runtime, id) {
  assert(PLATFORMS[id], `unknown platform ${id}`);
  assert.equal(identity.runtime, runtime, `launcher did not execute ${runtime}`);
  assert.equal(identity.os, PLATFORMS[id].os, `${runtime}: wrong runtime OS for ${id}`);
  assert.equal(identity.cpu, PLATFORMS[id].cpu, `${runtime}: wrong runtime CPU for ${id}`);
  assert(identity.version && identity.execPath, `${runtime}: empty runtime identity`);

// The main package: static optionalDependencies, exactly the eight platform packages at its own version, no scripts.
const main = JSON.parse(readFileSync(join(nodeDir, "package.json"), "utf8"));
assert.equal(main.scripts, undefined, "the main package has no scripts (no lifecycle script, ever)");
assert.deepEqual(
  main.optionalDependencies,
  Object.fromEntries(Object.keys(PLATFORMS).map((id) => [`hugr-omni-${id}`, main.version])),
  `package.json: optionalDependencies must be the ${Object.keys(PLATFORMS).length} platform packages, each at version ${main.version}`,
);

rmSync(out, { recursive: true, force: true });
mkdirSync(join(out, "tarballs"), { recursive: true });

/** Stages `files` (name in the package -> source) with `json` as its package.json, packs it, and checks the tarball. */
function pack(json, files, supervisor) {
  const dir = join(out, "stage", json.name);
  mkdirSync(dir, { recursive: true });
  for (const [name, from] of Object.entries(files)) copyFileSync(from, join(dir, name));
  if (supervisor) chmodSync(join(dir, supervisor), 0o755);
  writeFileSync(join(dir, "package.json"), `${JSON.stringify(json, null, 2)}\n`);
  npm(["pack", "--silent", "--pack-destination", "../../tarballs"], dir);

  // The tarball as it is: exactly these files, the supervisor executable, no scripts. (`tar` runs next to it: GNU tar
  // reads `C:\...` as a remote host.)
  const tgz = `${json.name}-${json.version}.tgz`;
  const tar = (...args) => execFileSync("tar", args, { cwd: join(out, "tarballs"), encoding: "utf8" });
  const listing = tar("-tvzf", tgz).trim().split("\n").map((l) => l.split(/\s+/));
  assert.deepEqual(listing.map((l) => l.at(-1)).sort(), ["package.json", ...Object.keys(files)].map((n) => `package/${n}`).sort(), `${tgz}: unexpected contents`);
  if (supervisor && process.platform !== "win32") {
    assert(listing.find((l) => l.at(-1) === `package/${supervisor}`)[0].startsWith("-rwx"), `${supervisor} lost its execute bit in ${tgz}`);
  }
  assert.equal(JSON.parse(tar("-xzOf", tgz, "package/package.json")).scripts, undefined, `${tgz} has scripts`);

for (const id of ids) {
  const p = PLATFORMS[id];
  const exe = `hugr-omni-supervisor${p.os === "win32" ? ".exe" : ""}`;
  const addon = join(target, p.addon, "release", p.lib);
  const supervisor = join(target, p.supervisor, "release", exe);
  console.log(`binary proof ${id}: ${JSON.stringify(validateBinaries(id, addon, supervisor))}`);

  pack(
    {
      name: `hugr-omni-${id}`,
      version: main.version,
      description: `The native addon and the supervisor of hugr-omni for ${id}. Install hugr-omni, not this package.`,
      license: main.license,
      repository: main.repository,
      homepage: main.homepage,
      bugs: main.bugs,
      os: [p.os],
      cpu: [p.cpu],
      ...(p.libc && { libc: [p.libc] }),
      main: "hugr-omni.node",
      files: ["hugr-omni.node", exe, ...Object.keys(licenses)],
      engines: main.engines,
    },
    { "hugr-omni.node": addon, [exe]: supervisor, ...licenses },
    exe,
  );
}

// The main package is bindings/node/package.json plus the licenses (npm itself adds a README, once W18 writes one).
const readme = join(nodeDir, "README.md");
pack({ ...main, files: [...main.files, ...Object.keys(licenses)] }, {
  ...Object.fromEntries(main.files.map((f) => [f, join(nodeDir, f)])),
  ...licenses,
  ...(existsSync(readme) && { "README.md": readme }),
});

// A package that only its `libc` keeps off this machine (the other libc's package, same os and cpu) gets a stub tarball
// (its package.json, no addon): Bun and Deno do not read `libc` (measured: bun 1.x, deno 2.x) and install it, as they
// will install the published one. npm must skip it; under Bun and Deno the loader must still pick this machine's package
// (the stub has no addon, and the decoy below would fail the quickstart).
const libcOnly = absent.filter((other) => PLATFORMS[other].os === process.platform && PLATFORMS[other].cpu === process.arch);
for (const other of libcOnly) {
  const { os, cpu, libc: lib } = PLATFORMS[other];
  const dir = join(tmp, "stubs", other);
  mkdirSync(join(dir, "package"), { recursive: true });
  const json = { name: `hugr-omni-${other}`, version, os: [os], cpu: [cpu], libc: [lib], main: "hugr-omni.node" };
  writeFileSync(join(dir, "package", "package.json"), JSON.stringify(json));
  execFileSync("tar", ["-czf", "stub.tgz", "package"], { cwd: dir });
  entries.push({ file: join(dir, "stub.tgz"), json });
}

// Nothing that points at a checkout; a clean cache for the package manager under test.
const env = { ...process.env };
for (const v of ["HUGR_OMNI_ADDON", "HUGR_OMNI_SUPERVISOR", "CARGO_TARGET_DIR"]) delete env[v];
const sh = promisify(exec);
async function timed(command, extraEnv) {
  const start = performance.now();
  const { stdout, stderr } = await sh(command, { cwd: project, env: { ...env, ...extraEnv }, timeout: 30_000, killSignal: "SIGKILL" });
  return { out: stdout + stderr, seconds: (performance.now() - start) / 1000 };

// Installed: the main package and only this platform's, no lifecycle script, nothing compiled, supervisor next to the addon.
const main = createRequire(join(project, "package.json")).resolve("hugr-omni");
const addon = createRequire(main).resolve(`hugr-omni-${id}`);
for (const other of Object.keys(PLATFORMS).filter((o) => o !== id)) {
  if (runtime !== "node" && libcOnly.includes(other)) continue; // declared: Bun and Deno do not read `libc`
  assert.throws(() => createRequire(main).resolve(`hugr-omni-${other}/package.json`), `hugr-omni-${other} must not be installed on ${id}`);
}
const supervisor = join(dirname(addon), process.platform === "win32" ? "hugr-omni-supervisor.exe" : "hugr-omni-supervisor");
assert(existsSync(supervisor), "the supervisor is not next to the addon");
const binaries = validateBinaries(id, addon, supervisor);
const crtImports = {};
if (process.platform === "win32") {
  // H5 (x64 and arm64): built with a static C runtime, so no Visual C++ Redistributable is needed. KERNEL32 is the
  // positive control: an import table read as empty would otherwise pass.
  for (const file of [addon, supervisor]) {
    const dlls = peImports(readFileSync(file));
    assert(dlls.some((d) => /^kernel32\.dll$/i.test(d)), `${file}: its import table reads ${JSON.stringify(dlls)}, without KERNEL32.dll`);
    const crt = dlls.filter((d) => /^(vcruntime|msvcp)/i.test(d));
    assert.deepEqual(crt, [], `${file} needs the Visual C++ runtime (${crt.join(", ")}): build it with +crt-static (.cargo/config.toml)`);
    crtImports[file === addon ? "addon" : "supervisor"] = dlls;
  }
}
for (const dir of [dirname(main), dirname(addon)]) assert.equal(JSON.parse(readFileSync(join(dir, "package.json"), "utf8")).scripts, undefined, `${dir} has scripts`);
assert.match(installed.out, /hugr-omni/, "the install log is empty: the check below would pass on nothing");
assert.doesNotMatch(installed.out, /node-gyp|gyp ERR|cargo (build|install)|rustc|maturin/i, "the install compiled something");

// The platform package comes before a Cargo build: a decoy build where the loader would look (<project>/target) must not matter.
mkdirSync(join(project, "target", "debug"), { recursive: true });
writeFileSync(join(project, "target", "debug", { darwin: "libhugr_omni_node.dylib", win32: "hugr_omni_node.dll" }[process.platform] ?? "libhugr_omni_node.so"), "not a library");
const hello = await timed(run);
assert.match(hello.out, /^true /, "run() of the quickstart did not succeed");
assert.match(hello.out, /parentPid/, "processes() of the quickstart listed nothing");
console.log(`K9 ok  ${runtime}  ${id}  install ${installed.seconds.toFixed(1)} s  quickstart ${hello.seconds.toFixed(1)} s`);
const proofs = resolve(tarballs, "..", "proofs");
mkdirSync(proofs, { recursive: true });
writeFileSync(join(proofs, `${id}-${runtime}.json`), JSON.stringify({
  id, identity, runtimeBinary, binaries, crtImports,
  sha256: Object.fromEntries([["hugr_omni.node", addon], [process.platform === "win32" ? "hugr-omni-supervisor.exe" : "hugr-omni-supervisor", supervisor]].map(([name, file]) => [name, createHash("sha256").update(readFileSync(file)).digest("hex")])),
  tarballs: entries.filter((e) => names.includes(e.json.name)).map((e) => ({ name: e.json.name, sha256: createHash("sha256").update(readFileSync(e.file)).digest("hex") })),
  installSeconds: installed.seconds, quickstartSeconds: hello.seconds, quickstart: hello.out,
}, null, 2));

if (runtime === "node") {
  // The loader's messages, from the package alone (no platform package, no checkout): unsupported, and not installed.
  const alone = join(tmp, "alone");
  cpSync(dirname(main), join(alone, "node_modules", "hugr-omni"), { recursive: true });
  // The addon loads at the first use (WP-H), so the probe uses it: spawn() throws the loader's message.
  writeFileSync(join(alone, "probe.cjs"), `if (process.argv[2]) Object.defineProperty(process, "platform", { value: process.argv[2] });\ntry { require("hugr-omni").spawn("x"); console.log("LOADED"); } catch (e) { console.log(e.message); }\n`);
  const probe = (...args) => execFileSync(process.execPath, ["probe.cjs", ...args], { cwd: alone, env, encoding: "utf8" });
  const unsupported = probe("freebsd");
  for (const supported of Object.keys(PLATFORMS)) assert(unsupported.includes(supported), `the unsupported-platform message does not list ${supported}: ${unsupported}`);
  assert(unsupported.includes(`freebsd-${process.arch}`), `the unsupported-platform message does not name the platform: ${unsupported}`);
  assert.match(probe(), new RegExp(`hugr-omni-${id} .* is not installed`), "the missing-package message does not name the package");

test("empty, truncated, unknown and wrong-CPU artifact inputs fail closed", () => {
  const tmp = mkdtempSync(join(tmpdir(), "omni-artifact-control-"));
  try {
    const addon = join(tmp, "addon.node");
    const sup = join(tmp, "supervisor");
    writeFileSync(addon, Buffer.alloc(0));
    assert.throws(() => inspect(addon), /empty or truncated binary/);
    writeFileSync(addon, Buffer.alloc(64));
    assert.throws(() => inspect(addon), /unknown binary format/);
    assert.throws(() => validateBinaries("darwin-arm64", addon, sup), /supervisor is missing/);
    const macho = Buffer.alloc(64);
    macho.writeUInt32LE(0xfeedfacf, 0);
    macho.writeUInt32LE(0x0100000c, 4);
    writeFileSync(addon, macho);
    writeFileSync(sup, macho);
    assert.equal(validateBinaries("darwin-arm64", addon, sup).addon.cpu, "arm64");
    macho.writeUInt32LE(0x01000007, 4);
    writeFileSync(addon, macho);
    assert.throws(() => validateBinaries("darwin-arm64", addon, sup), /not a darwin-arm64 addon/);
    writeFileSync(addon, readFileSync(sup));
    writeFileSync(sup, macho);
    assert.throws(() => validateBinaries("darwin-arm64", addon, sup), /not a darwin-arm64 supervisor/);

test("runtime identity rejects emulated CPU, wrong OS and wrong launcher", () => {
  const identity = { runtime: "bun", os: "win32", cpu: "arm64", version: "1.4.2", execPath: "bun.exe" };
  validateRuntimeIdentity(identity, "bun", "win32-arm64-msvc");
  assert.throws(() => validateRuntimeIdentity({ ...identity, cpu: "x64" }, "bun", "win32-arm64-msvc"), /wrong runtime CPU/);
  assert.throws(() => validateRuntimeIdentity({ ...identity, os: "linux" }, "bun", "win32-arm64-msvc"), /wrong runtime OS/);
  assert.throws(() => validateRuntimeIdentity({ ...identity, runtime: "node" }, "bun", "win32-arm64-msvc"), /launcher did not execute bun/);
  assert.throws(() => validateRuntimeIdentity({ ...identity, version: "" }, "bun", "win32-arm64-msvc"), /empty runtime identity/);
});

test("existing-musl-guest build refuses unknown flag and non-musl target before Cargo", () => {
  const id = process.platform === "linux" ? `linux-${process.arch}-gnu` :
    process.platform === "darwin" ? `darwin-${process.arch}` : `win32-${process.arch}-msvc`;
  for (const [flag, diagnostic] of [["yes", "must be 1 or unset"], ["1", "existing guest mode requires a musl target"]]) {
    const result = spawnSync(process.execPath, [join(root, "scripts/build-artifacts.mjs"), id], {
      cwd: root, encoding: "utf8", env: { ...process.env, HUGR_BUILD_EXISTING_MUSL_GUEST: flag },
    });
    assert.notEqual(result.status, 0);
    assert(result.stderr.includes(diagnostic), result.stderr);
    assert(!result.stdout.includes("$ cargo"));
  }
});

if (process.env.HUGR_PROOF_REAL === "true") test("real shipped binaries pass; empty and wrong architecture mutations go red", () => {
  const id = process.env.HUGR_PROOF_ID;
  assert(PLATFORMS[id], "HUGR_PROOF_ID must name the built target");
  const artifacts = process.env.HUGR_PROOF_ARTIFACTS ?? join(root, "dist/omni");
  const addon = join(artifacts, id, "hugr_omni.node");
  const supervisor = join(artifacts, id, `hugr-omni-supervisor${PLATFORMS[id].os === "win32" ? ".exe" : ""}`);
  const tmp = mkdtempSync(join(tmpdir(), "omni-real-mutation-"));
  try {
    validateBinaries(id, addon, supervisor);
    const broken = join(tmp, "mutant");
    writeFileSync(broken, Buffer.alloc(0));
    assert.throws(() => validateBinaries(id, broken, supervisor), /empty or truncated binary/);
    for (const file of [addon, supervisor]) {
      const bytes = readFileSync(file);
      const format = inspect(file).format;
      if (format === "elf") bytes.writeUInt16LE(PLATFORMS[id].cpu === "x64" ? 183 : 62, 18);
      if (format === "macho") bytes.writeUInt32LE(PLATFORMS[id].cpu === "x64" ? 0x0100000c : 0x01000007, 4);
      if (format === "pe") bytes.writeUInt16LE(PLATFORMS[id].cpu === "x64" ? 0xaa64 : 0x8664, bytes.readUInt32LE(0x3c) + 4);
      writeFileSync(broken, bytes);
      assert.throws(() => validateBinaries(id, file === addon ? broken : addon, file === supervisor ? broken : supervisor), new RegExp(`not a ${id} ${file === addon ? "addon" : "supervisor"}`));
    }
    console.log(`mutation proof ${id}: empty artifact, addon CPU and supervisor CPU rejected; original bytes accepted`);

const args = process.argv.slice(2);
const outAt = args.indexOf("--out");
const out = resolve(root, outAt >= 0 ? (args.splice(outAt, 2)[1] ?? "") : "dist/omni");
assert(outAt < 0 || out !== root, "--out needs a directory");
const [id, ...extra] = args;
assert(id && extra.length === 0, `usage: node scripts/build-artifacts.mjs <id> [--out <dir>] (id: one of ${Object.keys(PLATFORMS).join(", ")})`);
const p = BUILDS[id];
assert(p, `unknown platform ${id} (one of ${Object.keys(PLATFORMS).join(", ")})`);
assert.equal(process.platform, PLATFORMS[id].os, `${id} requires its native OS`);
assert.equal(process.arch, PLATFORMS[id].cpu, `${id} requires its native CPU`);
assert(process.env.HUGR_BUILD_EXISTING_MUSL_GUEST === undefined || process.env.HUGR_BUILD_EXISTING_MUSL_GUEST === "1",
  "HUGR_BUILD_EXISTING_MUSL_GUEST must be 1 or unset");
assert(!process.env.HUGR_BUILD_EXISTING_MUSL_GUEST || p.build === "alpine", "existing guest mode requires a musl target");
// This entry never creates a container. Caller owns its pinned guest, namespaces,
// writable checkout, toolchain caches and teardown. Flag alone proves no ABI.

const prefix = read("git", ["rev-parse", "--show-prefix"]).trim().replace(/\/$/, "");
const source = {
  headSHA: read("git", ["rev-parse", "HEAD"]).trim(),
  treeHash: read("git", ["rev-parse", "HEAD^{tree}"]).trim(),
  omniTreeHash: read("git", ["rev-parse", prefix ? `HEAD:${prefix}` : "HEAD^{tree}"]).trim(),
};
if (process.env.HUGR_PROOF_HEAD) assert.equal(source.headSHA, process.env.HUGR_PROOF_HEAD, "checkout is not the current PR head");
console.log(`source proof ${JSON.stringify(source)}`);
const checks = {};
const existingGuest = process.env.HUGR_BUILD_EXISTING_MUSL_GUEST === "1" ? verifyExistingMuslGuest(id) : undefined;

if (p.build === "zig") {
  // glibc Linux: the addon at the glibc 2.17 floor (zig), the supervisor static (musl).
  run("cargo", ["zigbuild", "--release", "-p", "hugr-omni-node", "--target", `${p.addon}.2.17`]);
  run("cargo", ["build", "--release", "-p", "omni-supervisor", "--target", p.supervisor]);
  // The highest GLIBC_ version the addon's dynamic symbols need. The positive control is that one is named at all.
  const versions = read("objdump", ["-T", addon]).match(/GLIBC_[0-9.]*/g) ?? [];
  const floor = versions.map((v) => [v, v.slice(6).split(".").map(Number)]).sort(([, a], [, b]) => {
    for (let i = 0; i < Math.max(a.length, b.length); i++) if ((a[i] ?? 0) !== (b[i] ?? 0)) return (a[i] ?? 0) - (b[i] ?? 0);
    return 0;
  }).at(-1)?.[0];
  assert.equal(floor, "GLIBC_2.17", `the addon needs ${floor ?? "no GLIBC_ version (objdump read nothing)"}, not the 2.17 floor`);
  checks.glibcFloor = floor;
  console.log(`glibc floor proof ${id}: ${floor}`);
} else if (p.build === "alpine") {
  // musl Linux, natively on Alpine (as napi-rs builds it): the supervisor static (the target's default), the addon a
  // cdylib that links musl dynamically (-crt-static, set here and not in .cargo/config.toml: it must not reach the
  // supervisor), so a musl Node or Bun can dlopen it. The container's CPU is the host's. The image writes ./target.
  assert(target === join(root, "target"), "the alpine build writes ./target: unset CARGO_TARGET_DIR");
  if (existingGuest) {
    checks.existingMuslGuest = existingGuest;
    run("cargo", ["build", "--locked", "--release", "-p", "omni-supervisor", "--target", p.supervisor]);
    run("cargo", ["build", "--locked", "--release", "-p", "hugr-omni-node", "--target", p.addon],
      { RUSTFLAGS: "-C target-feature=-crt-static" });
  } else run("docker", ["run", "--rm", "-v", `${root}:/w`, "-w", "/w", "rust:1-alpine", "sh", "-euc", `
    apk add --no-cache gcc musl-dev >/dev/null
    rustup toolchain install
    cargo build --release -p omni-supervisor --target ${p.supervisor}
    RUSTFLAGS="-C target-feature=-crt-static" cargo build --release -p hugr-omni-node --target ${p.addon}`]);
  const dynamic = read("readelf", ["-d", addon]);
  console.log(dynamic);
  assert.match(dynamic, /NEEDED.*\[(libc\.musl-[^\]]*|libc\.so)\]/, "the addon does not link musl dynamically");

function verifyExistingMuslGuest(id) {
  assert.equal(process.platform, "linux", "EXISTING_MUSL_GUEST_LINUX_REQUIRED");
  const cpu = PLATFORMS[id].cpu === "x64" ? "x86_64" : "aarch64";
  assert.equal(machine(), cpu, "EXISTING_MUSL_GUEST_NATIVE_CPU_MISMATCH");
  const runtime = inspect("/proc/self/exe");
  assert.equal(runtime.format, "elf", "EXISTING_MUSL_GUEST_ELF_REQUIRED");
  assert.equal(runtime.cpu, PLATFORMS[id].cpu, "EXISTING_MUSL_GUEST_ELF_CPU_MISMATCH");
  assert(runtime.needed.some((n) => n === `libc.musl-${cpu}.so.1` || n === "libc.so") &&
    !runtime.needed.includes("libc.so.6"), "EXISTING_MUSL_GUEST_NODE_ABI_MISMATCH");
  const maps = readFileSync("/proc/self/maps", "utf8").trim().split("\n").map((line) => {
    const fields = /^\S+\s+([rwxps-]{4})\s+\S+\s+([0-9a-f]+):([0-9a-f]+)\s+(\d+)(?:\s+(.*))?$/.exec(line);
    assert(fields, "EXISTING_MUSL_GUEST_MAPS_INVALID");
    return { permissions: fields[1], major: parseInt(fields[2], 16), minor: parseInt(fields[3], 16), inode: BigInt(fields[4]), path: fields[5] };
  });
  assert(maps.length > 0, "EXISTING_MUSL_GUEST_MAPS_EMPTY");
  assert(!maps.some((m) => m.path && /(?:libc\.so\.6|libgcompat|qemu)/.test(m.path)), "EXISTING_MUSL_GUEST_COMPAT_OR_EMULATION_REFUSED");
  const library = realpathSync(`/lib/ld-musl-${cpu}.so.1`);
  const stat = statSync(library, { bigint: true });
  const major = Number((stat.dev >> 8n & 0xfffn) | (stat.dev >> 32n & 0xfffff000n));
  const minor = Number((stat.dev & 0xffn) | (stat.dev >> 12n & 0xffffff00n));
  assert(maps.some((m) => m.path === library && m.permissions.includes("x") && m.inode === stat.ino && m.major === major && m.minor === minor),
    "EXISTING_MUSL_GUEST_LIBC_NOT_LOADED");
  const rustHost = read("rustc", ["-vV"]).split("\n").find((line) => line.startsWith("host: "));
  assert.equal(rustHost, `host: ${cpu}-unknown-linux-musl`, "EXISTING_MUSL_GUEST_RUST_HOST_MISMATCH");
  return { cpu, library, inode: String(stat.ino), device: `${major}:${minor}`, runtime, rustHost };

const os = { linux: "linux", darwin: "darwin", win32: "windows" }[process.platform];
const release = process.argv.includes("--release") || process.env.RELEASE === "1" || /^v/.test(process.env.CI_COMMIT_TAG ?? "");
const target = process.env.CARGO_TARGET_DIR ?? "target";
const filter = (process.env.TEST_FILTER ?? "").split(" ").filter(Boolean);

// Release only.
{ name: "musl supervisor", on: ["linux"], release: true, cmd: ["cargo", "build", "--release", "-p", "omni-supervisor", "--target", "x86_64-unknown-linux-musl"] },
{ name: "musl supervisor is static", on: ["linux"], release: true, run: () => {
  const elf = spawnSync("readelf", ["-l", join(target, "x86_64-unknown-linux-musl/release/hugr-omni-supervisor")], { encoding: "utf8" });
  return elf.status === 0 && !elf.stdout.includes("INTERP") ? null : "the supervisor is dynamically linked (or readelf failed)";
} },
{ name: "supervisor suite (musl)", on: ["linux"], release: true, cmd: ["cargo", "test", "-p", "omni-supervisor", "--no-fail-fast"],
